return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n==1) ? 0 : (n==2) ? 1 : (n != 8 && n != 11) ? 2 : 3;','language'=>'cy','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:02+00:00','po-revision-date'=>'2026-10-31T05:53:02+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Yn llenwi cyfieithiadau coll ar gyfer y ategion a\'r themâu sydd eisoes wedi\'u gosod ar eich gwefan.','Translations'=>'Cyfieithiadau','Babilim Settings'=>'Gosodiadau Babilim','Settings'=>'Gosodiadau','You are not allowed to do this.'=>'Ni chaniateir i chi wneud hyn.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Dewiswch lai o gydrannau: uchafswm o %1$d gweithred ar bob rhediad (dewisoch %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Nid yw\'r gydran honno wedi\'i gosod ar y wefan hon, felly ni ellir gofyn am gyfieithiad ar ei chyfer.','Already installed.'=>'Wedi\'i osod eisoes.','Downloaded and installed.'=>'Wedi\'i lawrlwytho a\'i osod.','Babilim has not been enabled for this site yet.'=>'Nid yw Babilim wedi\'i alluogi ar gyfer y wefan hon eto.','No build is available to download for this locale.'=>'Nid oes adeiladwaith ar gael i\'w lawrlwytho ar gyfer y locale hwn.','Rolled back to the previous build.'=>'Wedi dychwelyd i\'r adeiladwaith blaenorol.','Rolled back and reported.'=>'Wedi dychwelyd ac adrodd.','Rolled back, but the report could not be sent: %s'=>'Wedi dychwelyd, ond ni ellid anfon yr adroddiad: %s','Removed.'=>'Wedi\'i dynnu.','Translation requested.'=>'Gofynnwyd am gyfieithiad.','This component was already uploaded. Babilim is checking it now.'=>'Cafodd y gydran hon ei huwchlwytho eisoes. Mae Babilim yn ei gwirio nawr.','Upload cancelled.'=>'Diddymwyd yr uwchlwytho.','Upload complete — translation requested.'=>'Uwchlwytho wedi\'i gwblhau — gofynnwyd am gyfieithiad.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Nid yw\'r gydran hon yn datgan rhif fersiwn, felly ni ellir gofyn am gyfieithiad ar ei chyfer.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Mae rhif fersiwn y gydran hon yn hirach na %d nod, na all Babilim ei drin, felly ni ellir gofyn am gyfieithiad ar ei chyfer.','A translation cannot be requested for that locale on this site right now.'=>'Ni ellir gofyn am gyfieithiad ar gyfer y locale hwnnw ar y wefan hon ar hyn o bryd.','Thank you. Your report was sent.'=>'Diolch. Anfonwyd eich adroddiad.','This report does not name a valid plugin or theme and locale.'=>'Nid yw\'r adroddiad hwn yn enwi ategyn neu thema a locale dilys.','Please choose a category for this report.'=>'Dewiswch Categori ar gyfer yr adroddiad hwn.','This report is missing a valid build to report against.'=>'Mae\'r adroddiad hwn yn brin o adeiladwaith dilys i adrodd yn ei erbyn.','This build is not one this site currently knows about for this component/locale.'=>'Nid yw\'r wefan hon yn adnabod yr adeiladwaith hwn ar hyn o bryd ar gyfer y cydran/locale hwn.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Mae\'r maes "%1$s" yn rhy hir: mae ganddo %2$d nod a\'r terfyn yw %3$d. Ni anfonwyd dim; byrhewch ef a rhowch gynnig arall arni.','Original string'=>'Llinyn gwreiddiol','String context'=>'Cyd-destun y llinyn','Current translation'=>'Cyfieithiad cyfredol','Suggested translation'=>'Cyfieithiad awgrymedig','Note (optional)'=>'Nodyn (dewisol)','Where you saw this (optional)'=>'Lle gwelsoch hyn (dewisol)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Mae cysoni Babilim wedi\'i oedi dros dro gan y gwasanaeth (cyfyngu cyfradd); bydd yn rhoi cynnig arall arni ar ôl %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Nid yw hwn yn god locale WordPress dilys. Ni chadwyd dim.','Settings saved.'=>'Cadwyd y gosodiadau.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Os yw hyn ymlaen, bydd dadosod hefyd yn dileu hunaniaeth y wefan hon. Ni ellir adfer y drwydded dalu sydd ynghlwm wrth y wefan hon yn awtomatig wedyn; byddai\'n rhaid i chi gysylltu â chymorth Babilim yn %s i\'w chael yn ôl.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Mae Babilim wedi\'i osod i ddileu hunaniaeth y wefan hon pan fydd yr ategyn yn cael ei ddileu. Ni ellid adfer y drwydded dalu sydd ynghlwm wrth y wefan hon yn awtomatig wedyn; byddai\'n rhaid i chi gysylltu â chymorth Babilim yn %s. I gadw\'r hunaniaeth, pwyswch Diddymu, dad-diciwch "Dileu holl ddata Babilim wrth ddadosod" yng ngosodiadau Babilim, a dadactifadu eto. Dadactifadu beth bynnag?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Mae gan y rhwydwaith hwn ormod o wefannau i\'w gwirio fesul un, ac efallai bod rhai ohonynt wedi\'u gosod i ddileu eu hunaniaeth Babilim pan fydd yr ategyn yn cael ei ddileu. Ni ellid adfer y drwydded dalu sydd ynghlwm wrth wefan o\'r fath yn awtomatig wedyn; byddai\'n rhaid i chi gysylltu â chymorth Babilim yn %s. I gadw\'r hunaniaethau, pwyswch Diddymu, dad-diciwch "Dileu holl ddata Babilim wrth ddadosod" yng ngosodiadau Babilim pob gwefan, a dadactifadu eto. Dadactifadu beth bynnag?','Open Babilim settings'=>'Agor gosodiadau Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Ni allai Babilim wirio\'r wefan hon, felly ni chaiff dim ei lawrlwytho na\'i osod.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Nid oedd modd i\'r gwasanaeth gyrraedd eich gwefan. Mae\'n debyg bod mur gwarchod, ategyn diogelwch neu reol gwesteiwr yn rhwystro\'r cais; caniatewch geisiadau i /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Cymerodd eich gwefan ormod o amser i ymateb. Rhowch gynnig arall arni nes ymlaen, a gwiriwch nad yw eich gwesteiwr yn rhy araf nac wedi\'i orlwytho.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Atebodd eich gwefan, ond nid gyda\'r hyn a ddisgwylid. Efallai bod y REST API wedi\'i ailysgrifennu gan ategyn arall, neu fod y pwynt terfyn hwnnw wedi\'i storio mewn storfa dros dro; eithriwch /wp-json/babilim/v1/challenge rhag storio dros dro ac ailysgrifennu.','Please check that your site can be reached from the internet, then try again.'=>'Gwiriwch fod modd cyrraedd eich gwefan o\'r rhyngrwyd, yna rhowch gynnig arall arni.','Re-verify'=>'Ailwirio','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Mae\'r wefan hon dros y maint y mae\'r gwasanaeth yn ei dderbyn mewn un cysoni, felly gadawyd rhai eitemau allan: %1$d cydran a %2$d iaith.','This site is verified.'=>'Mae\'r wefan hon wedi\'i gwirio.','Registration restarted.'=>'Cofrestru wedi ailddechrau.','Sync complete.'=>'Cysoni wedi\'i gwblhau.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Mae Babilim yn galluogi ac yn gwirio\'r wefan hon… Ail-lwythwch y dudalen hon neu arhoswch i\'r gwiriad a amserlenwyd orffen.','Babilim could not finish enabling (%1$s): %2$s'=>'Ni allai Babilim orffen galluogi (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Ni all gwesteiwr sydd ond yn gwasanaethu un cais PHP ar y tro gwblhau\'r cam hwn.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Mae Babilim wedi\'i analluogi. Ni chaiff dim mwy ei anfon; mae cyfieithiadau sydd eisoes wedi\'u gosod yn parhau i weithio.','Supplementary translation index rebuilt.'=>'Ailadeiladwyd y mynegai cyfieithiadau atodol.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Mae gosodiadau awtomatig bellach i ffwrdd; trowch nhw ymlaen eto yn y gosodiadau os ydych eu heisiau.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Mae Babilim yn dod o hyd i\'r ategion a\'r themâu ar y wefan hon sydd heb gyfieithiad ar gyfer eich iaith ac yn gosod un ar gyfer pob un.','Languages found on this site: %s.'=>'Ieithoedd a ganfuwyd ar y wefan hon: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Gellir gosod cyfieithiadau sydd ar gael gydag un clic, a gellir gofyn am rai coll. Ar ôl hynny, caiff cyfieithiadau newydd a diweddariadau eu gosod yn awtomatig (ar y cynllun rhad ac am ddim, dim ond ar gyfer ategion a themâu sydd eisoes yn defnyddio slot rhad ac am ddim).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Mae\'r cynllun rhad ac am ddim yn cwmpasu nifer cyfyngedig o ategion a themâu; dangosir eich cwota union yn Gosodiadau ar ôl i chi alluogi Babilim.','What is sent when you enable Babilim'=>'Beth a anfonir pan fyddwch yn galluogi Babilim','Enabling…'=>'Wrthi\'n galluogi…','Enable Babilim'=>'Galluogi Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Drwy glicio Galluogi, rydych yn cytuno i anfon yr wybodaeth a restrir uchod i Babilim.','Check again now'=>'Gwirio eto nawr','Babilim is enabling and checking this site… (last attempt: %s)'=>'Mae Babilim yn galluogi ac yn gwirio\'r wefan hon… (ymgais ddiwethaf: %s)','Check again'=>'Gwirio eto','No components synced yet.'=>'Dim cydrannau wedi\'u cysoni eto.','%1$s nothing to do.'=>'%1$s dim i\'w wneud.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Lawrlwytho swmp:','Bulk update:'=>'Diweddaru swmp:','Bulk request:'=>'Cais swmp:','per day'=>'y dydd','Wrong meaning'=>'Ystyr anghywir','Wrong term'=>'Term anghywir','Broken placeholder'=>'Dalfan toredig','Wrong for this context'=>'Anghywir ar gyfer y cyd-destun hwn','Wrong plural form'=>'Ffurf luosog anghywir','Negation reversed'=>'Negyddu wedi\'i wrthdroi','Translation does not load'=>'Nid yw\'r cyfieithiad yn llwytho','problem report categoryOther'=>'Arall','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Parhau…','Continue next batch (%d left)'=>'Parhau â\'r swp nesaf (%d ar ôl)','Search components'=>'Chwilio cydrannau','These are the languages this site uses. You can change them in %s.'=>'Dyma\'r ieithoedd y mae\'r wefan hon yn eu defnyddio. Gallwch eu newid yn %s.','Upload this component?'=>'Uwchlwytho\'r gydran hon?','There is no upload waiting for confirmation.'=>'Nid oes uwchlwytho yn aros am gadarnhad.','Back'=>'Yn ôl','To translate this component, Babilim needs its source.'=>'I gyfieithu\'r gydran hon, mae angen ei ffynhonnell ar Babilim.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Bydd holl gyfeiriadur ategyn neu thema %1$s (fersiwn %2$s) yn cael ei uwchlwytho i Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Os yw\'r cyfeiriadur hwnnw\'n cynnwys allweddi, logiau neu ddata cwsmeriaid, byddant yn cael eu huwchlwytho hefyd. Mae\'r gwasanaeth yn dileu ffeiliau sensitif cyffredin (ffurfwedd, amgylchedd, dympiau cronfa ddata, logiau, allweddi) ond ni all warantu ei fod yn dod o hyd i bopeth.','The upload is kept until you ask Babilim to delete it.'=>'Cedwir yr uwchlwythiad nes i chi ofyn i Babilim ei ddileu.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Caiff ei storio gan ddarparwr gwesteio\'r gwasanaeth a\'i brosesu gan fodelau AI i gynhyrchu\'r cyfieithiad.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Bydd y testun gwreiddiol a\'r cyfieithiadau a wneir ohono yn cael eu darparu i wefannau eraill sy\'n gosod yr un fersiwn.','By continuing you confirm that you have the right to upload this component.'=>'Drwy barhau rydych yn cadarnhau bod gennych yr hawl i uwchlwytho\'r cydran hwn.','Upload and request'=>'Uwchlwytho a gofyn','Uploading…'=>'Yn uwchlwytho…','Cancel'=>'Canslo','Uploading'=>'Yn uwchlwytho','There is no upload in progress.'=>'Nid oes uwchlwytho ar y gweill.','Uploading part %1$d of %2$d…'=>'Uwchlwytho rhan %1$d o %2$d…','Continue'=>'Parhau','Confirm'=>'Cadarnhau','Remove'=>'Dileu','Roll back'=>'Rholio\'n ôl','Nothing to confirm.'=>'Dim byd i\'w gadarnhau.','Choose a language'=>'Dewiswch iaith','Roll back and report'=>'Rholio\'n ôl a rhoi gwybod','Report a problem'=>'Adrodd problem','Nothing to choose.'=>'Dim byd i\'w ddewis.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Dewiswch yr iaith.','Supplementary translations'=>'Cyfieithiadau atodol','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Cyfraniad pob cydran ei hun at yr atodiad parth rhagosodedig a rennir ar gyfer pob locale.','Component'=>'Cydran','Language'=>'Iaith','Included in index'=>'Wedi\'i gynnwys yn y mynegai','Entries'=>'Cofnodion','Conflicting keys'=>'Allweddi sy\'n gwrthdaro','Yes'=>'Ydy','No — component inactive'=>'Nac ydy — cydran anweithredol','No — installed version differs from the active one'=>'Nac ydy — mae\'r fersiwn sydd wedi\'i gosod yn wahanol i\'r un gweithredol','No — component removed'=>'Nac ydy — cydran wedi\'i thynnu','No'=>'Na','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Dim ond gweinyddwr rhwydwaith all wneud hyn, oherwydd mae\'n newid ffeiliau cyfieithu a rennir gan bob gwefan ar y rhwydwaith hwn.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Ni allai Babilim orffen dilysu\'r wefan hon (ni allai\'r gwasanaeth gysylltu\'n ôl â hi). Mae\'r cofrestru wedi\'i oedi.','This site already has an active registration that can no longer be recovered automatically.'=>'Mae gan y wefan hon gofrestriad gweithredol na ellir ei adfer yn awtomatig mwyach.','Restart registration'=>'Ailddechrau cofrestru','Babilim settings'=>'Gosodiadau Babilim','General'=>'Cyffredinol','Advanced'=>'Uwch','Languages'=>'Ieithoedd','Automatic installs'=>'Gosodiadau awtomatig','Install available translations automatically'=>'Gosod cyfieithiadau sydd ar gael yn awtomatig','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Ar 